 .tm-mobile[data-mobile-version][data-preview="v3"] .preview-work-story { --work-space:52px; }
 .tm-mobile[data-mobile-version][data-preview="v3"] .preview-work-story .m-chapter { padding-block:var(--work-space); border:0; }
 .tm-mobile[data-mobile-version][data-preview="v3"] .preview-work-story h2 { font-size:clamp(2rem,8.5vw,2.75rem); line-height:1.08; text-wrap:balance; margin:0 0 28px; }
 .tm-mobile[data-mobile-version][data-preview="v3"] .preview-work-story p { text-align:left; hyphens:none; }
 .tm-mobile[data-mobile-version][data-preview="v3"] .preview-work-story :is(h3,p,li) { overflow-wrap:break-word; }
 .tm-mobile[data-mobile-version][data-preview="v3"] .preview-work-welcome { padding-block:24px 48px; text-align:center; }
 .tm-mobile[data-mobile-version][data-preview="v3"] .preview-work-welcome .preview-work-manifesto { font-family:var(--ff-display); font-size:1.875rem; line-height:1.25; color:var(--m-heading); text-align:center; margin:0; }
 .tm-mobile[data-mobile-version][data-preview="v3"] .preview-work-welcome .preview-work-location { margin:20px auto 24px; max-width:27ch; font-size:.875rem; text-align:center; }
 .tm-mobile[data-mobile-version][data-preview="v3"] .preview-work-button { display:inline-flex; justify-content:center; align-items:center; gap:18px; max-width:100%; min-height:56px; padding:16px 24px; border-radius:80px; background:#754437; color:#f4f0eb; font-family:var(--ff-body); font-size:.9375rem; font-weight:600; line-height:1.35; text-align:center; text-decoration:none; }
 .tm-mobile[data-mobile-version][data-preview="v3"] .preview-work-button:focus-visible { outline:2px solid currentColor; outline-offset:5px; }
 .tm-mobile[data-mobile-version][data-preview="v3"] .preview-work-button .m-arrow { width:22px; height:22px; flex-shrink:0; }
 .tm-mobile[data-mobile-version][data-preview="v3"] .preview-work-needs { padding-top:24px; }
 .tm-mobile[data-mobile-version][data-preview="v3"] .preview-work-journey { margin:0 0 32px; }
 .tm-mobile[data-mobile-version][data-preview="v3"] .preview-work-journey h3 { font-size:1.375rem; margin:0 0 10px; }
