 .tm-mobile[data-mobile-version][data-preview="v3"] .preview-work-needs .preview-barriers article { background:rgba(244,240,235,.26); border-color:rgba(117,68,55,.38); border-radius:30px 8px 30px 8px; }
 .tm-mobile[data-mobile-version][data-preview="v3"] .preview-work-story .preview-work-bridge { font-family:var(--ff-display); font-size:1.75rem; line-height:1.25; color:var(--m-accent); margin:12px 0 0; }
 .tm-mobile[data-mobile-version][data-preview="v3"] .preview-work-fit { padding-top:12px; }
