 .tm-mobile[data-mobile-version][data-preview="v3"] .preview-work-contrast .preview-comparison { margin-bottom:0; }
 /* Exact published process material: original Ashes, normal blend, 1024 px tile. */
 .tm-mobile[data-mobile-version][data-preview="v3"] .preview-work-ink { position:relative; background:#1c1c1a var(--tex-cotton) repeat; background-size:1024px 1024px; background-blend-mode:normal; padding-bottom:40px; }
 .tm-mobile[data-mobile-version][data-preview="v3"] .preview-work-ink > .m-chapter { background:none; }
 .tm-mobile[data-mobile-version][data-preview="v3"] .preview-work-ink::before { content:''; position:absolute; left:0; right:0; top:-33px; height:34px; background:inherit; mask:url('/media/material/edge-strata-top.png') center 23%/160% 120px no-repeat; pointer-events:none; }
 .tm-mobile[data-mobile-version][data-preview="v3"] .preview-work-ink::after { content:''; position:absolute; left:0; right:0; bottom:-1px; height:34px; background:var(--sandstone) var(--tex-sand); background-size:768px 768px; mask-image:url('/media/material/edge-strata.png'),linear-gradient(#fff,#fff); mask-size:160% 120px,100% 100%; mask-position:center -75px,center; mask-repeat:no-repeat; mask-composite:exclude,add; pointer-events:none; }
 .tm-mobile[data-mobile-version][data-preview="v3"] .preview-work-ink :is(.m-between,.m-process)::before,
 .tm-mobile[data-mobile-version][data-preview="v3"] .preview-work-ink :is(.m-between,.m-process)::after { display:none; }
 .tm-mobile[data-mobile-version][data-preview="v3"] .preview-work-start > .m-inner > h2 { font-size:clamp(2.75rem,13vw,4rem); text-align:center; margin-bottom:16px; }
