 .tm-mobile[data-mobile-version][data-preview="v3"] .preview-work-included article:nth-child(even) { margin-left:32px; }
 .tm-mobile[data-mobile-version][data-preview="v3"] .preview-work-included h3 { margin:0 0 10px; font-size:1.625rem; color:var(--m-accent); line-height:1.2; }
 .tm-mobile[data-mobile-version][data-preview="v3"] .preview-work-included p { margin:0; font-size:1rem; line-height:1.6; }
 .tm-mobile[data-mobile-version][data-preview="v3"] .preview-work-week { margin-top:40px; padding:24px 0 0; border-top:1px solid var(--m-rule); }
 .tm-mobile[data-mobile-version][data-preview="v3"] .preview-work-week > h3 { font-size:1.625rem; margin:0 0 16px; }
 .tm-mobile[data-mobile-version][data-preview="v3"] .preview-work-week > p { font-size:1rem; line-height:1.65; }
 .tm-mobile[data-mobile-version][data-preview="v3"] .preview-work-reason { font-family:var(--ff-display); font-size:1.5rem; line-height:1.4; margin:32px 0 0; }
 .tm-mobile[data-mobile-version][data-preview="v3"] .preview-work-price { margin-top:32px; padding:28px 24px; border:1px solid rgba(239,150,107,.42); border-radius:36px 8px 36px 8px; }
 .tm-mobile[data-mobile-version][data-preview="v3"] .preview-work-price p { margin:0; font-size:1.125rem; }
 .tm-mobile[data-mobile-version][data-preview="v3"] .preview-work-price .small { font-size:.875rem; margin-top:12px; }
 .tm-mobile[data-mobile-version][data-preview="v3"] .preview-work-price .preview-work-button { background:#e5d8c4; color:#1c1c1a; width:100%; margin-top:24px; }
 .tm-mobile[data-mobile-version][data-preview="v3"] .preview-work-price .m-text-link { display:flex; margin-top:24px; }
 .tm-mobile[data-mobile-version][data-preview="v3"] .preview-work-process { padding-top:12px; }
 .tm-mobile[data-mobile-version][data-preview="v3"] .preview-work-process .m-equipment { width:54%; margin:0 0 20px auto; }
 .tm-mobile[data-mobile-version][data-preview="v3"] .preview-work-process .m-process-steps { margin:0; gap:28px; }
 .tm-mobile[data-mobile-version][data-preview="v3"] .preview-work-process .m-process-steps h3 { font-size:1.5rem; }
 .tm-mobile[data-mobile-version][data-preview="v3"] .preview-work-process .m-process-steps p { font-size:1rem; line-height:1.6; }
 .tm-mobile[data-mobile-version][data-preview="v3"] .preview-work-process .m-text-link { margin-top:24px; }
 .tm-mobile[data-mobile-version][data-preview="v3"] .preview-work-terrain { display:block; width:100%; height:56px; color:var(--m-accent); }
