 .tm-mobile[data-mobile-version][data-preview="v3"] .preview-work-person .m-photo { float:left; width:44%; aspect-ratio:3/5; margin:0 20px 10px 0; border-radius:44% 44% 10px 10px; overflow:hidden; }
